-- System 03: integrate existing immutable media foundation. No hosted Storage DDL or activation.
begin;
create table if not exists submission_media.upload_files (
 asset_id uuid primary key, submission_id uuid not null,
 role text not null check(role in ('master','instrumental','clean','alternate','stem','supporting','artwork')),
 label text not null check(length(label) between 1 and 80 and label !~ '[[:cntrl:]]'),
 retired_at timestamptz, retired_reason text check(retired_reason in ('replaced','removed')),
 created_at timestamptz not null default clock_timestamp(),
 foreign key(submission_id,asset_id) references submission_media.assets(submission_id,id) on delete restrict,
 check((retired_at is null)=(retired_reason is null))
);
create unique index if not exists upload_files_active_label on submission_media.upload_files(submission_id,role,label) where retired_at is null;
alter table submission_media.upload_files enable row level security;
alter table submission_media.upload_files force row level security;
revoke all on submission_media.upload_files from public,anon,authenticated,service_role;
create or replace function submission_media.guard_upload_file() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='DELETE' or (new.asset_id,new.submission_id,new.role,new.label,new.created_at) is distinct from (old.asset_id,old.submission_id,old.role,old.label,old.created_at) or old.retired_at is not null then raise exception 'Immutable upload history' using errcode='42501';end if;return new;end$$;
revoke all on function submission_media.guard_upload_file() from public,anon,authenticated,service_role;
drop trigger if exists upload_history on submission_media.upload_files;
create trigger upload_history before update or delete on submission_media.upload_files for each row execute function submission_media.guard_upload_file();
alter table submission_media.operations drop constraint if exists operations_action_check;
alter table submission_media.operations add constraint operations_action_check check(action in ('create','reserve','select_region','generate_preview','accept_preview','accept_artwork','request_review','decide_review','bind_track','adopt_legacy','retry_job','reserve_upload','remove_upload','save_upload_metadata','submit_uploads'));
alter table submission_media.events drop constraint if exists events_event_type_check;
alter table submission_media.events add constraint events_event_type_check check(event_type in ('checkpoint_created','asset_reserved','upload_observed','validation_started','validation_passed','validation_failed','waveform_generated','region_changed','preview_requested','preview_generated','preview_accepted','artwork_accepted','asset_activated','asset_superseded','master_review_requested','master_review_approved','master_review_rejected','track_bound','legacy_adoption_requested','job_retried','upload_removed','upload_metadata_saved'));

create or replace function public.media_upload_reserve(p_submission uuid,p_role text,p_label text,p_filename text,p_bytes bigint,p_revision bigint,p_key uuid,p_replaces uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare s submission_media.submissions; o submission_media.operations; aid uuid:=gen_random_uuid(); previous submission_media.upload_files; kind text; expires timestamptz:=clock_timestamp()+interval '24 hours'; begin
 perform submission_media.require_capability('reservations');perform pg_advisory_xact_lock(hashtextextended('media-quota:'||submission_media.require_actor('artist')::text,0));s:=submission_media.lock_owned(p_submission,null);
 if p_role is null or p_role not in ('master','instrumental','clean','alternate','stem','supporting','artwork') or p_bytes is null or p_bytes<=0 or p_bytes>(case when p_role='artwork' then 10000000 else 250000000 end) or p_label is null or p_label<>btrim(p_label) or length(p_label) not between 1 and 80 or p_label~'[[:cntrl:]]' or p_filename is null or length(p_filename) not between 1 and 255 or p_filename~'[[:cntrl:]/\\]' then raise exception 'Invalid upload reservation' using errcode='22023';end if;
 if (p_role='artwork' and p_filename !~* '[.](jpg|jpeg|png|webp)$') or (p_role<>'artwork' and p_filename !~* '[.](wav|aif|aiff|aifc|flac)$') then raise exception 'Unsupported upload format' using errcode='22023';end if;
 o:=submission_media.begin_operation(s.id,'reserve_upload',p_key,jsonb_build_object('role',p_role,'label',p_label,'filename',p_filename,'bytes',p_bytes,'revision',p_revision,'replaces',p_replaces));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if exists(select 1 from submission_media.master_reviews where submission_id=s.id and state='pending') then raise exception 'Review in progress' using errcode='55000';end if;
 if p_replaces is not null then select * into previous from submission_media.upload_files where asset_id=p_replaces and submission_id=s.id and retired_at is null and role=p_role and label=p_label for update;if not found then raise exception 'Invalid replacement' using errcode='42501';end if;
 elsif p_role in ('master','artwork') then select * into previous from submission_media.upload_files where submission_id=s.id and role=p_role and retired_at is null for update;
 elsif exists(select 1 from submission_media.upload_files where submission_id=s.id and role=p_role and label=p_label and retired_at is null) then raise exception 'Choose the exact file to replace' using errcode='22023';end if;
 if (select count(*) from submission_media.assets a join submission_media.submissions x on x.id=a.submission_id where x.owner_id=s.owner_id and a.technical_state in ('reserved','uploaded','verifying') and (a.technical_state<>'reserved' or a.reservation_expires_at>now()) and not exists(select 1 from submission_media.upload_files f where f.asset_id=a.id and f.retired_at is not null))>=4 or (select count(*) from submission_media.assets a join submission_media.submissions x on x.id=a.submission_id where x.owner_id=s.owner_id and a.created_at>now()-interval '24 hours' and a.origin='upload')>=20 then raise exception 'Upload limit reached' using errcode='54000';end if;
 kind:=case when p_role='artwork' then 'artwork' else 'source_master' end;
 if previous.asset_id is not null then update submission_media.upload_files set retired_at=clock_timestamp(),retired_reason='replaced' where asset_id=previous.asset_id;end if;
 insert into submission_media.assets(id,submission_id,operation_id,kind,origin,display_filename,declared_bytes,bucket,object_path,reservation_expires_at) values(aid,s.id,o.id,kind,'upload',p_filename,p_bytes,case when kind='artwork' then 'submission-artwork' else 'submission-source' end,s.owner_id::text||'/'||s.id::text||'/'||aid::text||'/original',expires);
 insert into submission_media.upload_files(asset_id,submission_id,role,label) values(aid,s.id,p_role,p_label);
 if p_role='master' then update submission_media.submissions set working_master_id=aid,accepted_preview_id=null,selection_master_id=null,selection_start_ms=null,selection_end_ms=null where id=s.id;end if;
 perform submission_media.append_event(s.id,'asset_reserved',aid,o.id,null,null,'artist',jsonb_build_object('previous_asset_id',previous.asset_id));
 return submission_media.finish_operation(o.id,jsonb_build_object('asset_id',aid,'revision',submission_media.bump(s.id),'expires_at',expires));end$$;

create or replace function public.media_upload_destination(p_submission uuid,p_asset uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s submission_media.submissions;begin
 s:=submission_media.lock_owned(p_submission,null);
 if not exists(select 1 from submission_media.upload_files where submission_id=s.id and asset_id=p_asset and retired_at is null) then raise exception 'Upload unavailable' using errcode='42501';end if;
 return submission_media.upload_destination(p_asset);end$$;
create or replace function public.media_upload_confirm(p_submission uuid,p_asset uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s submission_media.submissions;begin
 s:=submission_media.lock_owned(p_submission,null);if not exists(select 1 from submission_media.upload_files where submission_id=s.id and asset_id=p_asset and retired_at is null) then raise exception 'Upload unavailable' using errcode='42501';end if;
 return submission_media.observe_upload(p_asset);end$$;
create or replace function public.media_upload_remove(p_submission uuid,p_asset uuid,p_revision bigint,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s submission_media.submissions; o submission_media.operations;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'remove_upload',p_key,jsonb_build_object('asset',p_asset,'revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if not exists(select 1 from submission_media.upload_files where submission_id=s.id and asset_id=p_asset and retired_at is null) or p_asset in (s.current_master_id,s.current_preview_id,s.current_artwork_id) or exists(select 1 from submission_media.assets where id=p_asset and accepted_at is not null) or exists(select 1 from submission_media.master_reviews where submission_id=s.id and state='pending') or exists(select 1 from licensing_private.source_asset_links where master_id=p_asset) then raise exception 'Referenced media cannot be removed' using errcode='42501';end if;
 update submission_media.upload_files set retired_at=clock_timestamp(),retired_reason='removed' where asset_id=p_asset;
 update submission_media.assets set orphan_candidate_at=clock_timestamp() where id=p_asset;
 if s.working_master_id=p_asset then update submission_media.submissions set working_master_id=null,accepted_preview_id=null,selection_master_id=null,selection_start_ms=null,selection_end_ms=null where id=s.id;end if;
 perform submission_media.append_event(s.id,'upload_removed',p_asset,o.id,null,null,'artist');return submission_media.finish_operation(o.id,jsonb_build_object('revision',submission_media.bump(s.id)));end$$;

create or replace function submission_media.upload_state(p_submission uuid,p_admin boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare s submission_media.submissions;u uuid;begin
 perform submission_media.require_capability('reads');if p_admin then u:=submission_media.require_actor('admin');select * into s from submission_media.submissions where id=p_submission;else s:=submission_media.lock_owned(p_submission,null);end if;if s.id is null then raise exception 'Upload unavailable' using errcode='42501';end if;
 return jsonb_build_object('submission_id',s.id,'track_id',s.track_id,'track_slug',(select slug from public.tracks where id=s.track_id),'revision',s.revision,'source',submission_media.asset_dto(s.working_master_id),'current_source',submission_media.asset_dto(s.current_master_id),'preview',submission_media.asset_dto(s.accepted_preview_id),'artwork',submission_media.asset_dto(s.accepted_artwork_id),'selection',jsonb_build_object('start_ms',s.selection_start_ms,'end_ms',s.selection_end_ms),
 'waveform',(select submission_media.asset_dto(id) from submission_media.assets where source_asset_id=s.working_master_id and kind='waveform'),
 'files',coalesce((select jsonb_agg(jsonb_build_object('asset',submission_media.asset_dto(f.asset_id),'role',f.role,'label',f.label,'retired',f.retired_at is not null,'reason',f.retired_reason,'expires_at',a.reservation_expires_at) order by f.created_at) from submission_media.upload_files f join submission_media.assets a on a.id=f.asset_id where f.submission_id=s.id),'[]'),
 'derivatives',coalesce((select jsonb_agg(submission_media.asset_dto(a.id)) from submission_media.assets a where a.submission_id=s.id and a.source_asset_id=s.working_master_id),'[]'),
 'jobs',coalesce((select jsonb_agg(jsonb_build_object('id',j.id,'asset_id',j.asset_id,'state',j.state,'attempt',j.attempt,'max_attempts',j.max_attempts,'retryable',j.retryable,'available_at',j.available_at,'error_code',a.safe_error_code) order by j.created_at) from submission_media.jobs j join submission_media.assets a on a.id=j.asset_id where j.submission_id=s.id),'[]'),
 'integrity',case when p_admin then coalesce((select jsonb_agg(jsonb_build_object('asset_id',id,'sha256',encode(sha256,'hex'),'version',storage_version,'verified_at',verified_at)) from submission_media.assets where submission_id=s.id),'[]') else '[]'::jsonb end,
 'metadata',(select jsonb_build_object('title',title,'description',description,'genre',genre,'subgenre',subgenre,'moods',array_to_string(moods,', '),'bpm',bpm,'key',musical_key,'releaseYear',release_year,'instrumental',instrumental,'vocals',vocals,'explicit',explicit) from public.tracks where id=s.track_id),
 'review',(select jsonb_build_object('id',id,'state',state) from submission_media.master_reviews where submission_id=s.id order by created_at desc limit 1),'last_saved_at',s.last_saved_at);end$$;
revoke all on function submission_media.upload_state(uuid,boolean) from public,anon,authenticated,service_role;
create or replace function public.media_upload_read(p_submission uuid) returns jsonb language sql security invoker set search_path='' as $$select submission_media.upload_state(p_submission,false)$$;
-- The wrapper must execute its private helper under its verified owner; the helper checks the live actor.
alter function public.media_upload_read(uuid) security definer;
create or replace function public.media_upload_admin_read(p_submission uuid) returns jsonb language sql security definer set search_path='' as $$select submission_media.upload_state(p_submission,true)$$;
create or replace function public.media_upload_list() returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=submission_media.require_actor('artist');begin
 perform submission_media.require_capability('reads');return coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'track_id',s.track_id,'title',coalesce(t.title,'Untitled audio draft'),'saved_at',s.last_saved_at) order by s.last_saved_at desc) from (select * from submission_media.submissions where owner_id=u order by last_saved_at desc limit 50) s left join public.tracks t on t.id=s.track_id),'[]');end$$;

create or replace function public.media_upload_save_metadata(p_submission uuid,p_data jsonb,p_revision bigint,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s submission_media.submissions; o submission_media.operations;t uuid;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'save_upload_metadata',p_key,jsonb_build_object('data',p_data,'revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>12000 or (p_data-array['title','description','genre','subgenre','moods','bpm','key','releaseYear','instrumental','vocals','explicit'])<>'{}'::jsonb or coalesce(length(p_data->>'title'),0) not between 2 and 160 or coalesce(length(p_data->>'description'),0) not between 20 and 5000 or coalesce(length(p_data->>'genre'),0) not between 1 and 80 or coalesce(length(p_data->>'subgenre'),0) not between 1 and 80 or coalesce(length(p_data->>'moods'),0) not between 1 and 500 or coalesce(length(p_data->>'key'),0) not between 1 and 40 or coalesce(p_data->>'bpm','')!~'^[0-9]{2,3}$' or (p_data->>'bpm')::integer not between 40 and 220 or coalesce(p_data->>'releaseYear','')!~'^[0-9]{4}$' or (p_data->>'releaseYear')::integer not between 1950 and 2030 or jsonb_typeof(p_data->'instrumental') is distinct from 'boolean' or jsonb_typeof(p_data->'vocals') is distinct from 'boolean' or jsonb_typeof(p_data->'explicit') is distinct from 'boolean' or ((p_data->>'instrumental')::boolean and (p_data->>'vocals')::boolean) then raise exception 'Complete the track metadata' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(p_data) e where e.key in ('title','description','genre','subgenre','moods','key') and (jsonb_typeof(e.value) is distinct from 'string' or e.value#>>'{}' is distinct from btrim(e.value#>>'{}'))) then raise exception 'Invalid metadata text' using errcode='22023';end if;
 if s.track_id is null and not exists(select 1 from submission_media.assets where id=s.working_master_id and technical_state='ready') then raise exception 'Validated master required before catalog draft creation' using errcode='22023';end if;
 if s.track_id is null then
  t:=gen_random_uuid();insert into public.tracks(id,artist_user_id,title,slug,description,genre,subgenre,moods,bpm,musical_key,duration_seconds,release_year,instrumental,vocals,explicit,status) values(t,s.owner_id,p_data->>'title','upload-'||t::text,p_data->>'description',p_data->>'genre',p_data->>'subgenre',string_to_array(p_data->>'moods',','),(p_data->>'bpm')::integer,p_data->>'key',(select ceil(duration_us::numeric/1000000)::integer from submission_media.assets where id=s.working_master_id),(p_data->>'releaseYear')::integer,(p_data->>'instrumental')::boolean,(p_data->>'vocals')::boolean,(p_data->>'explicit')::boolean,'draft');update submission_media.submissions set track_id=t where id=s.id;
 else
  t:=s.track_id;perform 1 from public.tracks where id=t and artist_user_id=s.owner_id and status='draft' for update;if not found then raise exception 'Submitted metadata requires the canonical review workflow' using errcode='42501';end if;
  update public.tracks set title=p_data->>'title',description=p_data->>'description',genre=p_data->>'genre',subgenre=p_data->>'subgenre',moods=string_to_array(p_data->>'moods',','),bpm=(p_data->>'bpm')::integer,musical_key=p_data->>'key',release_year=(p_data->>'releaseYear')::integer,instrumental=(p_data->>'instrumental')::boolean,vocals=(p_data->>'vocals')::boolean,explicit=(p_data->>'explicit')::boolean where id=t;
 end if;
 perform submission_media.append_event(s.id,'upload_metadata_saved',null,o.id,null,null,'artist');return submission_media.finish_operation(o.id,jsonb_build_object('track_id',t,'revision',submission_media.bump(s.id)));end$$;

create or replace function public.media_upload_submit(p_submission uuid,p_revision bigint,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s submission_media.submissions;o submission_media.operations;r jsonb;prior_status public.track_status;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'submit_uploads',p_key,jsonb_build_object('revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if s.track_id is null or s.working_master_id is null or s.accepted_preview_id is null or not exists(select 1 from submission_media.assets where id=s.working_master_id and technical_state='ready') or not exists(select 1 from submission_media.assets where source_asset_id=s.working_master_id and kind='waveform' and technical_state='ready') or exists(select 1 from submission_media.upload_files f join submission_media.assets a on a.id=f.asset_id where f.submission_id=s.id and f.retired_at is null and a.technical_state<>'ready') then raise exception 'Validated Master, waveform, accepted Preview and complete uploads required' using errcode='22023';end if;
 select status into prior_status from public.tracks where id=s.track_id and artist_user_id=s.owner_id for update;
 if prior_status is null or prior_status not in ('draft','pending_review','approved') then raise exception 'Track unavailable for review' using errcode='42501';end if;
 if prior_status<>'approved' then update public.tracks set duration_seconds=(select ceil(duration_us::numeric/1000000)::integer from submission_media.assets where id=s.working_master_id),status='pending_review' where id=s.track_id and artist_user_id=s.owner_id;end if;
 r:=public.media_request_master_review(s.id,s.working_master_id,s.accepted_preview_id,s.revision,gen_random_uuid());return submission_media.finish_operation(o.id,r||jsonb_build_object('track_id',s.track_id,'is_resubmission',prior_status<>'draft'));end$$;

create or replace function public.media_upload_find(p_track uuid) returns uuid language plpgsql security definer set search_path='' as $$declare u uuid;result uuid;begin
 perform submission_media.require_capability('reads');if public.current_app_role()='admin' then u:=submission_media.require_actor('admin');select id into result from submission_media.submissions where track_id=p_track;else u:=submission_media.require_actor('artist');select id into result from submission_media.submissions where track_id=p_track and owner_id=u;end if;return result;end$$;

-- Capability material is returned only to a server endpoint after live actor authorization.
create or replace function public.media_upload_playback(p_submission uuid,p_asset uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s submission_media.submissions;a submission_media.assets;begin
 perform submission_media.require_capability('reads');if public.current_app_role()='admin' then perform submission_media.require_actor('admin');select * into s from submission_media.submissions where id=p_submission;else s:=submission_media.lock_owned(p_submission,null);end if;
 select * into a from submission_media.assets where submission_id=s.id and id=p_asset and kind in ('buyer_preview','waveform') and technical_state='ready' and source_asset_id=s.working_master_id;
 if not found or exists(select 1 from submission_media.upload_files where asset_id=a.source_asset_id and retired_at is not null) or not exists(select 1 from storage.objects where id=a.storage_object_id and version=a.storage_version and bucket_id=a.bucket and name=a.object_path) or not exists(select 1 from storage.buckets where id=a.bucket and not public) then raise exception 'Media unavailable' using errcode='42501';end if;
 return jsonb_build_object('asset_id',a.id,'bucket',a.bucket,'path',a.object_path,'sha256',encode(a.sha256,'hex'),'bytes',a.storage_bytes,'kind',a.kind,'version',a.storage_version);end$$;
-- Do not let a caller use Data API RPC to obtain private paths. Server uses a narrowly
-- authorized service-only resolver after deriving and verifying the actor itself.
revoke all on function public.media_upload_playback(uuid,uuid) from public,anon,authenticated,service_role;
create or replace function public.media_upload_playback_authorized(p_actor uuid,p_submission uuid,p_asset uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
 perform submission_media.require_capability('reads');if auth.role() is distinct from 'service_role' then raise exception 'Server authorization required' using errcode='42501';end if;
 -- This resolver remains private to the trusted server; authorize owner or canonical
 -- MFA Admin through the authenticated resolver below before it is invoked.
 if not exists(select 1 from public.user_profiles where id=p_actor and role in ('artist','admin')) then raise exception 'Actor unavailable' using errcode='42501';end if;
 select jsonb_build_object('asset_id',a.id,'bucket',a.bucket,'path',a.object_path,'sha256',encode(a.sha256,'hex'),'bytes',a.storage_bytes,'kind',a.kind,'version',a.storage_version) into result from submission_media.assets a join submission_media.submissions s on s.id=a.submission_id join storage.objects x on x.id=a.storage_object_id and x.version=a.storage_version and x.bucket_id=a.bucket and x.name=a.object_path join storage.buckets b on b.id=a.bucket and not b.public where a.submission_id=p_submission and a.id=p_asset and a.source_asset_id=s.working_master_id and a.kind in ('buyer_preview','waveform') and a.technical_state='ready' and not exists(select 1 from submission_media.upload_files f where f.asset_id=a.source_asset_id and f.retired_at is not null) and (s.owner_id=p_actor or exists(select 1 from public.user_profiles where id=p_actor and role='admin'));
 if result is null then raise exception 'Media unavailable' using errcode='42501';end if;return result;end$$;
-- The canonical non-secret authorization result contains no Storage locator.
create or replace function public.media_upload_can_play(p_submission uuid,p_asset uuid) returns boolean language plpgsql security definer set search_path='' as $$begin perform public.media_upload_playback(p_submission,p_asset);return true;end$$;
revoke all on function public.media_upload_playback_authorized(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.media_upload_playback_authorized(uuid,uuid,uuid) to service_role;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('media_upload_reserve','media_upload_destination','media_upload_confirm','media_upload_remove','media_upload_read','media_upload_admin_read','media_upload_list','media_upload_save_metadata','media_upload_submit','media_upload_can_play','media_upload_find') loop execute format('revoke all on function %s from public,anon,service_role',f);execute format('grant execute on function %s to authenticated',f);end loop;
end$$;
commit;
